import java.util.*;
import java.io.*;

public class Main {
    static long[] jobSequencing(long[] deadline, long[] profit) {
        // Write your solution here
        return new long[]{0, 0};
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int n = (int) in.nval;
        long[] deadline = new long[n], profit = new long[n];
        for (int i = 0; i < n; i++) {
            in.nextToken(); deadline[i] = (long) in.nval;
            in.nextToken(); profit[i] = (long) in.nval;
        }
        long[] r = jobSequencing(deadline, profit);
        System.out.println(r[0] + " " + r[1]);
    }
}
